[CmdletBinding()]param([Parameter(Mandatory)][string]$TargetRepo,[switch]$Json)
$repo=(Resolve-Path $TargetRepo).Path;$checks=@();$required=@('.engineering\implementation-workflow.md','.engineering\completion-gate.ps1','.engineering\discovery.ps1','.engineering\providers\grill.ps1','.engineering\issues');foreach($p in $required){$checks+=[pscustomobject]@{name=$p;status=if(Test-Path (Join-Path $repo $p)){'PASS'}else{'WARN'}}};$status=if(@($checks|Where-Object status -eq 'FAIL').Count){'FAIL'}else{'PASS'};if($Json){[pscustomobject]@{status=$status;checks=$checks}|ConvertTo-Json}else{$checks|ForEach-Object{"$($_.status) $($_.name)"};"DOCTOR: $status"};if($status -eq 'FAIL'){exit 1}
